insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000009', 1, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/01.jpg" alt="The New Thing Series — “See, I am doing a new thing!” Isaiah 43:19">', '<p>The New Thing Series — “See, I am doing a new thing!” Isaiah 43:19</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 2, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/02.jpg" alt="Make Room for a New Life — Something has to die for something new to live.">', '<p>Make Room for a New Life — Something has to die for something new to live.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 3, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/03.jpg" alt="Isaiah 43:16–19">', '<p>Isaiah 43:16–19</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 4, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/04.jpg" alt="We can have faith in what God did then and still have no expectation for what God can do now.">', '<p>We can have faith in what God did then and still have no expectation for what God can do now.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 5, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/05.jpg" alt="The danger is not that we forget what God has done. The danger is that we start believing God’s greatest works are all behind us.">', '<p>The danger is not that we forget what God has done. The danger is that we start believing God’s greatest works are all behind us.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 6, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/06.jpg" alt="God made a way through the water before. Now He’s going to make a way through the wilderness.">', '<p>God made a way through the water before. Now He’s going to make a way through the wilderness.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 7, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/07.jpg" alt="Same God. Same faithfulness. Different way.">', '<p>Same God. Same faithfulness. Different way.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 8, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/08.jpg" alt="Don’t become so attached to what God did yesterday that you fail to recognize what God is doing now.">', '<p>Don’t become so attached to what God did yesterday that you fail to recognize what God is doing now.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 9, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/09.jpg" alt="God’s people can know everything about what God has done and still struggle to recognize what God is doing.">', '<p>God’s people can know everything about what God has done and still struggle to recognize what God is doing.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 10, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/10.jpg" alt="Yesterday’s testimony was never meant to become today’s limitation.">', '<p>Yesterday’s testimony was never meant to become today’s limitation.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 11, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/11.jpg" alt="“Now it springs up; do you not perceive it?” — Isaiah 43:19">', '<p>“Now it springs up; do you not perceive it?” — Isaiah 43:19</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 12, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/12.jpg" alt="The new thing may already be beginning while we are still looking backward.">', '<p>The new thing may already be beginning while we are still looking backward.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 13, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/13.jpg" alt="We can kill a possibility before we have even allowed ourselves to see it.">', '<p>We can kill a possibility before we have even allowed ourselves to see it.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 14, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/14.jpg" alt="You will never begin what you refuse even to imagine.">', '<p>You will never begin what you refuse even to imagine.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 15, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/15.jpg" alt="Old does not necessarily mean bad.">', '<p>Old does not necessarily mean bad.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 16, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/16.jpg" alt="Making room for something new does not mean declaring that the old thing was wrong. It may simply mean it is time for a new season.">', '<p>Making room for something new does not mean declaring that the old thing was wrong. It may simply mean it is time for a new season.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 17, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/17.jpg" alt="We can hold something so tightly that we have no open hand with which to receive anything new.">', '<p>We can hold something so tightly that we have no open hand with which to receive anything new.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 18, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/18.jpg" alt="Death → Burial → Resurrection → Newness of life — Romans 6:3–4">', '<p>Death → Burial → Resurrection → Newness of life — Romans 6:3–4</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 19, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/19.jpg" alt="We want resurrection without a burial.">', '<p>We want resurrection without a burial.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 20, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/20.jpg" alt="We want God to give us something new without asking us to release anything old.">', '<p>We want God to give us something new without asking us to release anything old.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 21, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/21.jpg" alt="This is the tension of making room for new life.">', '<p>This is the tension of making room for new life.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 22, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/22.jpg" alt="The question is not simply: “What do I need to stop doing?”">', '<p>The question is not simply: “What do I need to stop doing?”</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 23, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/23.jpg" alt="The real question is: “What might God be trying to bring to life in me?”">', '<p>The real question is: “What might God be trying to bring to life in me?”</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 24, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/24.jpg" alt="Nicodemus — history, scripture, tradition, knowledge, identity, position. And Jesus tells him: “You must be born again.” — John 3:1–8">', '<p>Nicodemus — history, scripture, tradition, knowledge, identity, position. And Jesus tells him: “You must be born again.” — John 3:1–8</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 25, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/25.jpg" alt="Jesus does not offer Nicodemus an improvement. Jesus does not merely give him new information.">', '<p>Jesus does not offer Nicodemus an improvement. Jesus does not merely give him new information.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 26, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/26.jpg" alt="Nicodemus, you cannot enter this “new thing” as the same old man. You must be born again.">', '<p>Nicodemus, you cannot enter this “new thing” as the same old man. You must be born again.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 27, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/27.jpg" alt="Rebirth is not the completion of the journey. Rebirth is the beginning of the journey.">', '<p>Rebirth is not the completion of the journey. Rebirth is the beginning of the journey.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 28, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/28.jpg" alt="God is not only interested in doing something new around us. He wants to begin something new in us.">', '<p>God is not only interested in doing something new around us. He wants to begin something new in us.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 29, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/29.jpg" alt="Rebirth is the courage to begin again.">', '<p>Rebirth is the courage to begin again.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000009', 30, '<img class="slide-image" src="/sermons/make-room-for-a-new-life/slides/30.jpg" alt="What might God be trying to bring to life in me, and what am I going to have to let go of to make room for the new thing?">', '<p>What might God be trying to bring to life in me, and what am I going to have to let go of to make room for the new thing?</p>', null, null)
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
